CREATE TYPE public.app_role AS ENUM ('admin', 'mahasiswa');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '', nim text NOT NULL DEFAULT '');
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE TABLE public.user_roles (user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, PRIMARY KEY(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY role_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE FUNCTION public.create_user_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,name,nim) VALUES(NEW.id, COALESCE(NEW.raw_user_meta_data->>'name',''), COALESCE(NEW.raw_user_meta_data->>'nim','')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'mahasiswa'); RETURN NEW; END $$;
CREATE TRIGGER create_user_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_user_profile();
CREATE TABLE public.certificates (id text PRIMARY KEY, issuer_id uuid NOT NULL, recipient_email text NOT NULL, student_name text NOT NULL, student_nim text NOT NULL, activity_name text NOT NULL, activity_type text NOT NULL, organizer text NOT NULL, event_date date NOT NULL, issued_at date NOT NULL, file_hash text NOT NULL, file_path text NOT NULL, public_token uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(), transaction_id text UNIQUE, block_number bigint, issuer_wallet text, recorded_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.certificates TO authenticated; GRANT ALL ON public.certificates TO service_role;
ALTER TABLE public.certificates ENABLE ROW LEVEL SECURITY;
CREATE POLICY cert_read ON public.certificates FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR lower(recipient_email)=lower(auth.jwt()->>'email'));
CREATE TABLE public.activities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), message text NOT NULL, at timestamptz NOT NULL DEFAULT now(), kind text NOT NULL);
GRANT SELECT ON public.activities TO authenticated; GRANT ALL ON public.activities TO service_role;
ALTER TABLE public.activities ENABLE ROW LEVEL SECURITY;
CREATE POLICY activity_read ON public.activities FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY pdf_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='certificates' AND public.has_role(auth.uid(),'admin') AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY pdf_owner_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='certificates' AND EXISTS(SELECT 1 FROM public.certificates c WHERE c.file_path=name AND (public.has_role(auth.uid(),'admin') OR lower(c.recipient_email)=lower(auth.jwt()->>'email'))));